  "terms.s2.p": "आप जो फ़ाइलें इस्तेमाल करते हैं, उनकी ज़िम्मेदारी आपकी है। सिर्फ़ वही फ़ाइलें इस्तेमाल करें जिन पर आपका हक़ है। अपनी असली फ़ाइलों की एक कॉपी रखें।",
