  "terms.s3.p": "हम टूल को अच्छी तरह चलाने की कोशिश करते हैं, लेकिन वे जैसे हैं वैसे ही दिए जाते हैं, कोई वादा नहीं। इस्तेमाल या शेयर करने से पहले हर नतीजा जाँच लें, ख़ासकर निजी हिस्से छिपाने (Redact) के बाद। हस्ताक्षर करने पर आपके हस्ताक्षर की तस्वीर लगती है; यह प्रमाणित डिजिटल हस्ताक्षर नहीं है। कुछ PDF, जैसे ख़राब या ख़ास PDF, शायद न चलें।",
  "terms.s4.h": "सीमाएँ",
  "terms.s4.p": "क़ानून जितना इजाज़त देता है, उतना, टूल इस्तेमाल करने से डेटा खोने या किसी नुकसान की ज़िम्मेदारी हमारी नहीं है।",
  "terms.s5.h": "सही इस्तेमाल और बदलाव",
  "terms.s5.p": "टूल को किसी ग़ैर-क़ानूनी काम या दूसरों को नुकसान पहुँचाने के लिए इस्तेमाल न करें। हम ये शर्तें बदल सकते हैं, और नया रूप यहीं दिखेगा।",
  "contact.title": "संपर्क करें",
  "contact.intro": "सवाल, समस्या या सुझाव? हमें ईमेल भेजें।",
  "contact.s1.h": "ईमेल",
  "contact.s1.p": "नीचे दिए पते पर हमें लिखें। कृपया निजी फ़ाइलें न जोड़ें।",
  "contact.emailButton": "{email} को ईमेल करें",
  "privacy.seoDesc": "{site} आपकी प्राइवेसी कैसे बचाता है: PDF का सारा काम आपके ब्राउज़र में होता है और आपकी फ़ाइलें कभी अपलोड नहीं होतीं।",
  "terms.seoDesc": "{site} की इस्तेमाल की सरल शर्तें। यह ब्राउज़र में चलने वाले मुफ़्त PDF टूल का सेट है।",
  "contact.seoDesc": "{site} से संपर्क करें: हमारे मुफ़्त PDF टूल के बारे में अपने सवाल, समस्या या सुझाव ईमेल से भेजें।",
