  "tool.docxToPdf.step2": "बटन दबाएँ।",
  "tool.docxToPdf.step3": "अपनी PDF डाउनलोड करें।",
  "tool.docxToPdf.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
  "tool.docxToPdf.faq1a": "नहीं। सारा काम आपके ब्राउज़र में होता है। आपकी फ़ाइल आपके डिवाइस से बाहर नहीं जाती।",
