  "tool.docxToPdf.faq2a": "नहीं। यह सादा कन्वर्टर है। यह टेक्स्ट रखता है, पर तस्वीरें, फ़ॉन्ट, रंग या पेज का लेआउट नहीं। हू-ब-हू कॉपी के लिए Word का अपना 'PDF के रूप में सेव करें' इस्तेमाल करें।",
  "tool.xlsxToPdf.name": "Excel से PDF (सादा)",
