  "tool.xlsxToPdf.step1": "अपनी .xlsx फ़ाइल जोड़ें।",
  "tool.xlsxToPdf.step2": "बटन दबाएँ।",
  "tool.xlsxToPdf.step3": "अपनी PDF डाउनलोड करें।",
  "tool.xlsxToPdf.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
  "tool.xlsxToPdf.faq1a": "नहीं। सारा काम आपके ब्राउज़र में होता है। आपकी फ़ाइल आपके डिवाइस से बाहर नहीं जाती।",
