  "tool.pptxToPdf.name": "PowerPoint से PDF (सादा)",
  "tool.pptxToPdf.desc": "PowerPoint फ़ाइल के टेक्स्ट को सादी PDF में बदलें।",
  "tool.pptxToPdf.step1": "अपनी .pptx फ़ाइल जोड़ें।",
  "tool.pptxToPdf.step2": "बटन दबाएँ।",
  "tool.pptxToPdf.step3": "अपनी PDF डाउनलोड करें।",
  "tool.pptxToPdf.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
