  "tool.pdfToExcel.name": "PDF से Excel (मोटा, सिर्फ़ टेक्स्ट)",
  "tool.pdfToExcel.desc": "PDF का टेक्स्ट Excel फ़ाइल में कॉपी करें, लाइनें और कॉलम का अंदाज़ा लगाकर।",
  "tool.pdfToExcel.step1": "अपनी PDF फ़ाइल जोड़ें।",
  "tool.pdfToExcel.step2": "बटन दबाएँ।",
  "tool.pdfToExcel.step3": "अपनी Excel फ़ाइल डाउनलोड करें।",
  "tool.pdfToExcel.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
