  "tool.visitingCard.name": "विज़िटिंग कार्ड मेकर",
  "tool.visitingCard.desc": "छापने लायक दस विज़िटिंग कार्ड की शीट बनाएँ।",
  "tool.visitingCard.step1": "अपना नाम और संपर्क भरें।",
  "tool.visitingCard.step2": "रंग चुनें।",
  "tool.visitingCard.step3": "PDF बनाएँ, छापें और कार्ड काटें।",
  "tool.visitingCard.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
  "tool.visitingCard.faq1a": "नहीं। सारा काम आपके ब्राउज़र में होता है। आपकी फ़ाइल आपके डिवाइस से बाहर नहीं जाती।",
  "tool.visitingCard.faq2q": "कार्ड कितने बड़े हैं?",
  "tool.visitingCard.faq2a": "90 × 50 मिमी, जो आम आकार है। मोटे काग़ज़ पर 100% पर छापें।",
  "tool.certificateMaker.name": "प्रमाण पत्र मेकर",
  "tool.certificateMaker.desc": "प्रशंसा, सहभागिता या उपलब्धि का सादा प्रमाण पत्र बनाएँ।",
  "tool.certificateMaker.step1": "प्रकार चुनें और नाम व कारण लिखें।",
  "tool.certificateMaker.step2": "तारीख़ और हस्ताक्षरकर्ता जोड़ें।",
  "tool.certificateMaker.step3": "PDF बनाएँ, छापें और हाथ से हस्ताक्षर करें।",
  "tool.certificateMaker.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
  "tool.certificateMaker.faq1a": "नहीं। सारा काम आपके ब्राउज़र में होता है। आपकी फ़ाइल आपके डिवाइस से बाहर नहीं जाती।",
  "tool.certificateMaker.faq2q": "क्या यह आधिकारिक प्रमाण पत्र है?",
  "tool.certificateMaker.faq2a": "नहीं। यह स्कूलों, क्लबों और कार्यक्रमों के लिए सादा प्रमाण पत्र है। इस पर कोई मुहर नहीं है और यह किसी प्राधिकरण द्वारा जारी नहीं है।",
  "tool.namePlate.name": "नेम प्लेट मेकर",
  "tool.namePlate.desc": "डेस्क, दरवाज़े या कार्यक्रम के लिए बड़ी छपने लायक नेम प्लेट बनाएँ।",
  "tool.namePlate.step1": "नाम और उसके नीचे की छोटी लाइन लिखें।",
  "tool.namePlate.step2": "रंग चुनें।",
  "tool.namePlate.step3": "PDF बनाएँ और छापें।",
  "tool.namePlate.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
  "tool.namePlate.faq1a": "नहीं। सारा काम आपके ब्राउज़र में होता है। आपकी फ़ाइल आपके डिवाइस से बाहर नहीं जाती।",
