  "tool.calendarMaker.name": "कैलेंडर मेकर",
  "tool.calendarMaker.desc": "अंग्रेज़ी या हिंदी में छपने लायक साल का कैलेंडर या बड़ा महीना बनाएँ।",
  "tool.calendarMaker.step1": "साल (या महीना) चुनें।",
  "tool.calendarMaker.step2": "हफ़्ते की शुरुआत और भाषा चुनें।",
  "tool.calendarMaker.step3": "PDF बनाएँ और छापें।",
  "tool.calendarMaker.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
  "tool.calendarMaker.faq1a": "नहीं। सारा काम आपके ब्राउज़र में होता है। आपकी फ़ाइल आपके डिवाइस से बाहर नहीं जाती।",
  "tool.calendarMaker.faq2q": "क्या छुट्टियाँ दिखती हैं?",
  "tool.calendarMaker.faq2a": "नहीं। छुट्टियों और त्योहारों की तारीख़ें बदलती हैं और जगह के हिसाब से अलग होती हैं, इसलिए हम उन्हें नहीं छापते। बड़े महीने वाले पेज पर हाथ से लिख लें।",
  "tool.timetableMaker.name": "टाइमटेबल मेकर",
  "tool.timetableMaker.desc": "छपने लायक साप्ताहिक क्लास या पढ़ाई का टाइमटेबल बनाएँ।",
  "tool.timetableMaker.step1": "दिन और कालांश चुनें।",
  "tool.timetableMaker.step2": "हर खाने में लिखें क्या होगा।",
  "tool.timetableMaker.step3": "PDF बनाएँ और छापें।",
  "tool.timetableMaker.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
  "tool.timetableMaker.faq1a": "नहीं। सारा काम आपके ब्राउज़र में होता है। आपकी फ़ाइल आपके डिवाइस से बाहर नहीं जाती।",
  "tool.timetableMaker.faq2q": "मैं कितने कालांश रख सकता हूँ?",
