  "tool.hindiTyping.name": "हिंदी टाइपिंग (अंग्रेज़ी अक्षरों में)",
  "tool.hindiTyping.desc": "अंग्रेज़ी अक्षरों से हिंदी लिखें और उसे हिंदी टेक्स्ट के रूप में कॉपी करें।",
