  "tool.hindiTyping.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
  "tool.hindiTyping.faq1a": "नहीं। सारा काम आपके ब्राउज़र में होता है। आपकी फ़ाइल आपके डिवाइस से बाहर नहीं जाती।",
