  "tool.audioTrim.step1": "अपनी ऑडियो फ़ाइल जोड़ें।",
  "tool.audioTrim.step2": "शुरू और अंत के सेकंड तय करें।",
  "tool.audioTrim.step3": "काटें और WAV डाउनलोड करें।",
  "tool.audioTrim.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
  "tool.audioTrim.faq1a": "नहीं। सारा काम आपके ब्राउज़र में होता है। आपकी फ़ाइल आपके डिवाइस से बाहर नहीं जाती।",
  "tool.audioTrim.faq2q": "सिर्फ़ WAV क्यों, और सिर्फ़ छोटी फ़ाइलें क्यों?",
