  "tool.voiceRecorder.step2": "बोलें, फिर रोकें दबाएँ।",
  "tool.voiceRecorder.step3": "सुनें और डाउनलोड करें।",
  "tool.voiceRecorder.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
  "tool.voiceRecorder.faq1a": "नहीं। सारा काम आपके ब्राउज़र में होता है। आपकी फ़ाइल आपके डिवाइस से बाहर नहीं जाती।",
