  "tool.screenRecorder.name": "स्क्रीन रिकॉर्डर",
  "tool.screenRecorder.desc": "अपनी स्क्रीन, विंडो या टैब रिकॉर्ड करें और वीडियो डाउनलोड करें।",
  "tool.screenRecorder.step1": "शुरू बटन दबाएँ और चुनें क्या रिकॉर्ड करना है।",
  "tool.screenRecorder.step2": "जो दिखाना है करें, फिर रोकें दबाएँ।",
  "tool.screenRecorder.step3": "देखें और डाउनलोड करें।",
