  "tool.scanPack.step1": "अपनी फ़ोटो या स्कैन जोड़ें।",
  "tool.scanPack.step2": "उन्हें क्रम में रखें और A4, Letter या फ़िट, और खाली जगह चुनें।",
  "tool.scanPack.step3": "बटन दबाएँ और अपनी PDF डाउनलोड करें।",
  "tool.scanPack.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
  "tool.scanPack.faq1a": "नहीं। सारा काम आपके ब्राउज़र में होता है। आपकी फ़ाइल आपके डिवाइस से बाहर नहीं जाती।",
