  "tool.signaturePhoto.desc": "अपने दस्तख़त की फ़ोटो को पारदर्शी तस्वीर बनाएँ जो PDF पर लगाई जा सके।",
  "tool.signaturePhoto.step1": "सफ़ेद काग़ज़ पर अपने दस्तख़त की फ़ोटो खींचें।",
  "tool.signaturePhoto.step2": "स्याही का रंग चुनें और बटन दबाएँ।",
  "tool.signaturePhoto.step3": "तस्वीर सेव करें और PDF पर दस्तख़त में इस्तेमाल करें।",
  "tool.signaturePhoto.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
