  "tool.dateStamp.step1": "अपनी PDF जोड़ें।",
  "tool.dateStamp.step2": "नाम लिखें, और तारीख़, समय और कोना चुनें।",
  "tool.dateStamp.step3": "बटन दबाएँ और डाउनलोड करें।",
  "tool.dateStamp.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
  "tool.dateStamp.faq1a": "नहीं। सारा काम आपके ब्राउज़र में होता है। आपकी फ़ाइल आपके डिवाइस से बाहर नहीं जाती।",
