  "tool.metadataClean.name": "PDF की छिपी जानकारी साफ़ करें",
  "tool.metadataClean.desc": "PDF से लेखक, बनाने वाला, तारीख़ें और दूसरी छिपी जानकारी हटाएँ।",
  "tool.metadataClean.step1": "अपनी PDF जोड़ें।",
  "tool.metadataClean.step2": "देखें कि उसमें कौन-सी छिपी जानकारी है।",
  "tool.metadataClean.step3": "बटन दबाएँ और साफ़ कॉपी डाउनलोड करें।",
  "tool.metadataClean.faq1q": "क्या मेरी फ़ाइल अपलोड होती है?",
